package io.github.microcks.util.tracing;

import io.github.microcks.event.TraceEvent;
import io.opentelemetry.api.common.AttributeKey;
import io.opentelemetry.sdk.trace.ReadableSpan;

import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Utility class providing filtering helpers for trace events and spans. It offers wildcard/regex matching, extraction of
 * a {@link TraceEvent} from a list of spans, and matching of a {@link TraceEvent} against filter criteria.
 */
public final class SpanFilterUtil {

   /** Attribute key holding the service name. */
   private static final AttributeKey<String> SERVICE_NAME_KEY = AttributeKey.stringKey("service.name");
   /** Attribute key holding the operation name. */
   private static final AttributeKey<String> OPERATION_NAME_KEY = AttributeKey.stringKey("operation.name");
   /** Attribute key holding the client address. */
   private static final AttributeKey<String> CLIENT_ADDRESS_KEY = AttributeKey.stringKey("client.address");

   /**
    * Private constructor to prevent instantiation of utility class.
    */
   private SpanFilterUtil() {
      throw new UnsupportedOperationException("Utility class cannot be instantiated");
   }

   /**
    * Matches a value against a pattern supporting a simple wildcard and full regular expressions.
    *
    * @param pattern The pattern to match against. '*' matches any non-null value; otherwise it is interpreted as a full
    *                regex, falling back to exact string equality if the regex is invalid.
    * @param value   The value to test.
    * @return true if the value matches the pattern
    */
   public static boolean matchesWildcard(String pattern, String value) {
      if (pattern == null && value == null) {
         return true;
      }
      if (pattern == null || value == null) {
         return false;
      }
      if ("*".equals(pattern)) {
         return true;
      }
      try {
         return Pattern.matches(pattern, value);
      } catch (PatternSyntaxException e) {
         // Not a valid regex, fall back to exact string equality
         return pattern.equals(value);
      }
   }

   /**
    * Extracts a {@link TraceEvent} from the given spans, reading the 'service.name', 'operation.name' and
    * 'client.address' attributes.
    *
    * @param traceId The trace ID to associate with the resulting event
    * @param spans   The spans to extract attributes from
    * @return A {@link TraceEvent} with the extracted values, or null values when attributes are absent
    */
   public static TraceEvent extractTraceEvent(String traceId, List<ReadableSpan> spans) {
      String service = extractAttribute(spans, SERVICE_NAME_KEY);
      String operation = extractAttribute(spans, OPERATION_NAME_KEY);
      String clientAddress = extractAttribute(spans, CLIENT_ADDRESS_KEY);
      return new TraceEvent(traceId, service, operation, clientAddress);
   }

   /**
    * Checks whether the given {@link TraceEvent} matches the provided filter criteria using
    * {@link #matchesWildcard(String, String)} for each field.
    *
    * @param event         The event to test
    * @param service       The service pattern
    * @param operation     The operation pattern
    * @param clientAddress The client address pattern
    * @return true if all three event fields match their respective patterns
    */
   public static boolean matchesTraceEvent(TraceEvent event, String service, String operation, String clientAddress) {
      return matchesWildcard(service, event.service()) && matchesWildcard(operation, event.operation())
            && matchesWildcard(clientAddress, event.clientAddress());
   }

   /**
    * Finds the first non-null value of the given attribute key across the provided spans.
    *
    * @param spans The spans to inspect
    * @param key   The attribute key to read
    * @return The first non-null attribute value, or null if none of the spans carry the attribute
    */
   private static String extractAttribute(List<ReadableSpan> spans, AttributeKey<String> key) {
      if (spans == null) {
         return null;
      }
      for (ReadableSpan span : spans) {
         String value = span.getAttribute(key);
         if (value != null) {
            return value;
         }
      }
      return null;
   }
}
