package io.github.microcks.web;

import io.github.microcks.event.TraceEvent;
import io.github.microcks.service.SpanStorageService;
import io.github.microcks.util.tracing.SpanFilterUtil;
import io.opentelemetry.sdk.trace.ReadableSpan;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.io.IOException;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * Manages live subscriptions to trace events. Clients register {@link SseEmitter}s together with filter criteria and get
 * notified in real time whenever new trace data matching their criteria arrives.
 */
@Component
public class TraceSubscriptionManager {

   private static final Logger log = LoggerFactory.getLogger(TraceSubscriptionManager.class);

   private final SpanStorageService spanStorageService;

   /** Registered subscriptions. Uses a thread-safe collection as subscriptions may be added/removed concurrently. */
   private final Queue<Subscription> subscriptions = new ConcurrentLinkedQueue<>();

   /**
    * Creates a new {@code TraceSubscriptionManager}.
    *
    * @param spanStorageService The service used to retrieve spans for a trace
    */
   public TraceSubscriptionManager(SpanStorageService spanStorageService) {
      this.spanStorageService = spanStorageService;
   }

   /**
    * Registers an emitter to receive live trace events matching the given filter criteria. A heartbeat event is sent
    * immediately to confirm the subscription is active.
    *
    * @param emitter       The emitter to register
    * @param serviceName   The service name filter (pattern, may be '*' or a regex)
    * @param operationName The operation name filter (pattern, may be '*' or a regex)
    * @param clientAddress The client address filter (pattern, may be '*' or a regex)
    */
   public void subscribe(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
      Subscription subscription = new Subscription(emitter, serviceName, operationName, clientAddress);
      subscriptions.add(subscription);

      emitter.onCompletion(() -> subscriptions.remove(subscription));
      emitter.onTimeout(() -> subscriptions.remove(subscription));
      emitter.onError(t -> subscriptions.remove(subscription));

      // Send an immediate heartbeat to confirm the subscription is live.
      sendHeartbeat(emitter);
   }

   /**
    * Handles a {@link TraceEvent} by pushing the trace data to all matching subscribers.
    *
    * @param event The trace event that has been published
    */
   @EventListener
   public void onTraceUpdated(TraceEvent event) {
      List<ReadableSpan> spans = spanStorageService.getSpansForTrace(event.traceId());
      if (spans.isEmpty()) {
         // No span data available for this trace, nothing to stream.
         return;
      }

      // Build an enriched event from the actual spans so that all filterable attributes are available.
      TraceEvent enrichedEvent = SpanFilterUtil.extractTraceEvent(event.traceId(), spans);

      for (Subscription subscription : subscriptions) {
         if (SpanFilterUtil.matchesTraceEvent(enrichedEvent, subscription.serviceName(), subscription.operationName(),
               subscription.clientAddress())) {
            try {
               subscription.emitter().send(SseEmitter.event().name("trace").data(enrichedEvent));
            } catch (IOException e) {
               // The client is gone, complete the emitter so it gets cleaned up.
               log.debug("Failed to send trace event to subscriber, completing emitter", e);
               subscription.emitter().complete();
            }
         }
      }
   }

   /**
    * Sends a heartbeat event to all registered emitters to keep connections alive.
    */
   @Scheduled(fixedRate = 30000)
   public void sendHeartbeats() {
      for (Subscription subscription : subscriptions) {
         sendHeartbeat(subscription.emitter());
      }
   }

   /**
    * Sends a single heartbeat event to the given emitter.
    *
    * @param emitter The emitter to send a heartbeat to
    */
   private void sendHeartbeat(SseEmitter emitter) {
      try {
         emitter.send(SseEmitter.event().name("heartbeat").data("ping"));
      } catch (IOException e) {
         // The client is gone, complete the emitter so it gets cleaned up.
         log.debug("Failed to send heartbeat to subscriber, completing emitter", e);
         emitter.complete();
      }
   }

   /**
    * A registered subscription pairing an emitter with its filter criteria.
    *
    * @param emitter       The SSE emitter to push events to
    * @param serviceName   The service name filter pattern
    * @param operationName The operation name filter pattern
    * @param clientAddress The client address filter pattern
    */
   private record Subscription(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
   }
